mapper.select:
/* selectMasterMpStDeptPaymentStatsList */ SELECT (SELECT TEXT2 FROM ICOMCOD2 WHERE COMPANY_CODE = 'KRKORE0001' AND TYPE = 'C001' AND CODE = KEP_DEPT) AS DEPT_NM , (SELECT COM_NAME_LOC FROM ICOMCMPY WHERE COM_CODE = BUYER) AS BUYER_NM , DLY_TOT_CNT , DLY_CNT , DECODE(DLY_CNT,0,0, ROUND(DLY_CNT/DLY_TOT_CNT*100,1)) AS DLY_DLY_RATE , DECODE(LT_WORKING_DAY,0,0, ROUND(LT_WORKING_DAY/LT_TOT_DAY)) AS LT_WORKING_DAY , DECODE(LT_DAY,0,0, ROUND(LT_DAY/LT_TOT_DAY)) AS LT_DAY , DLY_TOT_CNT01 , DLY_DLY_CNT01 , DECODE(DLY_DLY_CNT01,0,0, ROUND(DLY_DLY_CNT01/DLY_TOT_CNT01*100,1)) AS DLY_DLY_RATE01 , DECODE(LT_WORKING_DAY01,0,0, ROUND(LT_WORKING_DAY01/LT_TOT_DAY01)) AS LT_WORKING_DAY01 , DECODE(LT_DAY01,0,0, ROUND(LT_DAY01/LT_TOT_DAY01)) AS LT_DAY01 , DLY_TOT_CNT02 , DLY_DLY_CNT02 , DECODE(DLY_DLY_CNT02,0,0, ROUND(DLY_DLY_CNT02/DLY_TOT_CNT02*100,1)) AS DLY_DLY_RATE02 , DECODE(LT_WORKING_DAY02,0,0, ROUND(LT_WORKING_DAY02/LT_TOT_DAY02)) AS LT_WORKING_DAY02 , DECODE(LT_DAY02,0,0, ROUND(LT_DAY02/LT_TOT_DAY02)) AS LT_DAY02 , DLY_TOT_CNT03 , DLY_DLY_CNT03 , DECODE(DLY_DLY_CNT03,0,0, ROUND(DLY_DLY_CNT03/DLY_TOT_CNT03*100,1)) AS DLY_DLY_RATE03 , DECODE(LT_WORKING_DAY03,0,0, ROUND(LT_WORKING_DAY03/LT_TOT_DAY03)) AS LT_WORKING_DAY03 , DECODE(LT_DAY03,0,0, ROUND(LT_DAY03/LT_TOT_DAY03)) AS LT_DAY03 , DLY_TOT_CNT04 , DLY_DLY_CNT04 , DECODE(DLY_DLY_CNT04,0,0, ROUND(DLY_DLY_CNT04/DLY_TOT_CNT04*100,1)) AS DLY_DLY_RATE04 , DECODE(LT_WORKING_DAY04,0,0, ROUND(LT_WORKING_DAY04/LT_TOT_DAY04)) AS LT_WORKING_DAY04 , DECODE(LT_DAY04,0,0, ROUND(LT_DAY04/LT_TOT_DAY04)) AS LT_DAY04 , DLY_TOT_CNT05 , DLY_DLY_CNT05 , DECODE(DLY_DLY_CNT05,0,0, ROUND(DLY_DLY_CNT05/DLY_TOT_CNT05*100,1)) AS DLY_DLY_RATE05 , DECODE(LT_WORKING_DAY05,0,0, ROUND(LT_WORKING_DAY05/LT_TOT_DAY05)) AS LT_WORKING_DAY05 , DECODE(LT_DAY05,0,0, ROUND(LT_DAY05/LT_TOT_DAY05)) AS LT_DAY05 , DLY_TOT_CNT06 , DLY_DLY_CNT06 , DECODE(DLY_DLY_CNT06,0,0, ROUND(DLY_DLY_CNT06/DLY_TOT_CNT06*100,1)) AS DLY_DLY_RATE06 , DECODE(LT_WORKING_DAY06,0,0, ROUND(LT_WORKING_DAY06/LT_TOT_DAY06)) AS LT_WORKING_DAY06 , DECODE(LT_DAY06,0,0, ROUND(LT_DAY06/LT_TOT_DAY06)) AS LT_DAY06 , DLY_TOT_CNT07 , DLY_DLY_CNT07 , DECODE(DLY_DLY_CNT07,0,0, ROUND(DLY_DLY_CNT07/DLY_TOT_CNT07*100,1)) AS DLY_DLY_RATE07 , DECODE(LT_WORKING_DAY07,0,0, ROUND(LT_WORKING_DAY07/LT_TOT_DAY07)) AS LT_WORKING_DAY07 , DECODE(LT_DAY07,0,0, ROUND(LT_DAY07/LT_TOT_DAY07)) AS LT_DAY07 , DLY_TOT_CNT08 , DLY_DLY_CNT08 , DECODE(DLY_DLY_CNT08,0,0, ROUND(DLY_DLY_CNT08/DLY_TOT_CNT08*100,1)) AS DLY_DLY_RATE08 , DECODE(LT_WORKING_DAY08,0,0, ROUND(LT_WORKING_DAY08/LT_TOT_DAY08)) AS LT_WORKING_DAY08 , DECODE(LT_DAY08,0,0, ROUND(LT_DAY08/LT_TOT_DAY08)) AS LT_DAY08 , DLY_TOT_CNT09 , DLY_DLY_CNT09 , DECODE(DLY_DLY_CNT09,0,0, ROUND(DLY_DLY_CNT09/DLY_TOT_CNT09*100,1)) AS DLY_DLY_RATE09 , DECODE(LT_WORKING_DAY09,0,0, ROUND(LT_WORKING_DAY09/LT_TOT_DAY09)) AS LT_WORKING_DAY09 , DECODE(LT_DAY09,0,0, ROUND(LT_DAY09/LT_TOT_DAY09)) AS LT_DAY09 , DLY_TOT_CNT10 , DLY_DLY_CNT10 , DECODE(DLY_DLY_CNT10,0,0, ROUND(DLY_DLY_CNT10/DLY_TOT_CNT10*100,1)) AS DLY_DLY_RATE10 , DECODE(LT_WORKING_DAY10,0,0, ROUND(LT_WORKING_DAY10/LT_TOT_DAY10)) AS LT_WORKING_DAY10 , DECODE(LT_DAY10,0,0, ROUND(LT_DAY10/LT_TOT_DAY10)) AS LT_DAY10 , DLY_TOT_CNT11 , DLY_DLY_CNT11 , DECODE(DLY_DLY_CNT11,0,0, ROUND(DLY_DLY_CNT11/DLY_TOT_CNT11*100,1)) AS DLY_DLY_RATE11 , DECODE(LT_WORKING_DAY11,0,0, ROUND(LT_WORKING_DAY11/LT_TOT_DAY11)) AS LT_WORKING_DAY11 , DECODE(LT_DAY11,0,0, ROUND(LT_DAY11/LT_TOT_DAY11)) AS LT_DAY11 , DLY_TOT_CNT12 , DLY_DLY_CNT12 , DECODE(DLY_DLY_CNT12,0,0, ROUND(DLY_DLY_CNT12/DLY_TOT_CNT12*100,1)) AS DLY_DLY_RATE12 , DECODE(LT_WORKING_DAY12,0,0, ROUND(LT_WORKING_DAY12/LT_TOT_DAY12)) AS LT_WORKING_DAY12 , DECODE(LT_DAY12,0,0, ROUND(LT_DAY12/LT_TOT_DAY12)) AS LT_DAY12 FROM ( SELECT MIS.KEP_DEPT , DECODE('N','N','X',KPI.BUYER) AS BUYER , SUM(DLY_TOT_CNT) AS DLY_TOT_CNT , SUM(DLY_CNT) AS DLY_CNT , SUM(LT_TOT_DAY) AS LT_TOT_DAY , SUM(LT_WORKING_DAY) AS LT_WORKING_DAY , SUM(LT_DAY) AS LT_DAY , SUM(DECODE(SUBSTR(YYYYMM,5,2),'01',DLY_TOT_CNT,0)) AS DLY_TOT_CNT01 , SUM(DECODE(SUBSTR(YYYYMM,5,2),'01',DLY_CNT,0)) AS DLY_DLY_CNT01 , SUM(DECODE(SUBSTR(YYYYMM,5,2),'01',LT_TOT_DAY,0)) AS LT_TOT_DAY01 , SUM(DECODE(SUBSTR(YYYYMM,5,2),'01',LT_WORKING_DAY,0)) AS LT_WORKING_DAY01 , SUM(DECODE(SUBSTR(YYYYMM,5,2),'01',LT_DAY,0)) AS LT_DAY01 , SUM(DECODE(SUBSTR(YYYYMM,5,2),'02',DLY_TOT_CNT,0)) AS DLY_TOT_CNT02 , SUM(DECODE(SUBSTR(YYYYMM,5,2),'02',DLY_CNT,0)) AS DLY_DLY_CNT02 , SUM(DECODE(SUBSTR(YYYYMM,5,2),'02',LT_TOT_DAY,0)) AS LT_TOT_DAY02 , SUM(DECODE(SUBSTR(YYYYMM,5,2),'02',LT_WORKING_DAY,0)) AS LT_WORKING_DAY02 , SUM(DECODE(SUBSTR(YYYYMM,5,2),'02',LT_DAY,0)) AS LT_DAY02 , SUM(DECODE(SUBSTR(YYYYMM,5,2),'03',DLY_TOT_CNT,0)) AS DLY_TOT_CNT03 , SUM(DECODE(SUBSTR(YYYYMM,5,2),'03',DLY_CNT,0)) AS DLY_DLY_CNT03 , SUM(DECODE(SUBSTR(YYYYMM,5,2),'03',LT_TOT_DAY,0)) AS LT_TOT_DAY03 , SUM(DECODE(SUBSTR(YYYYMM,5,2),'03',LT_WORKING_DAY,0)) AS LT_WORKING_DAY03 , SUM(DECODE(SUBSTR(YYYYMM,5,2),'03',LT_DAY,0)) AS LT_DAY03 , SUM(DECODE(SUBSTR(YYYYMM,5,2),'04',DLY_TOT_CNT,0)) AS DLY_TOT_CNT04 , SUM(DECODE(SUBSTR(YYYYMM,5,2),'04',DLY_CNT,0)) AS DLY_DLY_CNT04 , SUM(DECODE(SUBSTR(YYYYMM,5,2),'04',LT_TOT_DAY,0)) AS LT_TOT_DAY04 , SUM(DECODE(SUBSTR(YYYYMM,5,2),'04',LT_WORKING_DAY,0)) AS LT_WORKING_DAY04 , SUM(DECODE(SUBSTR(YYYYMM,5,2),'04',LT_DAY,0)) AS LT_DAY04 , SUM(DECODE(SUBSTR(YYYYMM,5,2),'05',DLY_TOT_CNT,0)) AS DLY_TOT_CNT05 , SUM(DECODE(SUBSTR(YYYYMM,5,2),'05',DLY_CNT,0)) AS DLY_DLY_CNT05 , SUM(DECODE(SUBSTR(YYYYMM,5,2),'05',LT_TOT_DAY,0)) AS LT_TOT_DAY05 , SUM(DECODE(SUBSTR(YYYYMM,5,2),'05',LT_WORKING_DAY,0)) AS LT_WORKING_DAY05 , SUM(DECODE(SUBSTR(YYYYMM,5,2),'05',LT_DAY,0)) AS LT_DAY05 , SUM(DECODE(SUBSTR(YYYYMM,5,2),'06',DLY_TOT_CNT,0)) AS DLY_TOT_CNT06 , SUM(DECODE(SUBSTR(YYYYMM,5,2),'06',DLY_CNT,0)) AS DLY_DLY_CNT06 , SUM(DECODE(SUBSTR(YYYYMM,5,2),'06',LT_TOT_DAY,0)) AS LT_TOT_DAY06 , SUM(DECODE(SUBSTR(YYYYMM,5,2),'06',LT_WORKING_DAY,0)) AS LT_WORKING_DAY06 , SUM(DECODE(SUBSTR(YYYYMM,5,2),'06',LT_DAY,0)) AS LT_DAY06 , SUM(DECODE(SUBSTR(YYYYMM,5,2),'07',DLY_TOT_CNT,0)) AS DLY_TOT_CNT07 , SUM(DECODE(SUBSTR(YYYYMM,5,2),'07',DLY_CNT,0)) AS DLY_DLY_CNT07 , SUM(DECODE(SUBSTR(YYYYMM,5,2),'07',LT_TOT_DAY,0)) AS LT_TOT_DAY07 , SUM(DECODE(SUBSTR(YYYYMM,5,2),'07',LT_WORKING_DAY,0)) AS LT_WORKING_DAY07 , SUM(DECODE(SUBSTR(YYYYMM,5,2),'07',LT_DAY,0)) AS LT_DAY07 , SUM(DECODE(SUBSTR(YYYYMM,5,2),'08',DLY_TOT_CNT,0)) AS DLY_TOT_CNT08 , SUM(DECODE(SUBSTR(YYYYMM,5,2),'08',DLY_CNT,0)) AS DLY_DLY_CNT08 , SUM(DECODE(SUBSTR(YYYYMM,5,2),'08',LT_TOT_DAY,0)) AS LT_TOT_DAY08 , SUM(DECODE(SUBSTR(YYYYMM,5,2),'08',LT_WORKING_DAY,0)) AS LT_WORKING_DAY08 , SUM(DECODE(SUBSTR(YYYYMM,5,2),'08',LT_DAY,0)) AS LT_DAY08 , SUM(DECODE(SUBSTR(YYYYMM,5,2),'09',DLY_TOT_CNT,0)) AS DLY_TOT_CNT09 , SUM(DECODE(SUBSTR(YYYYMM,5,2),'09',DLY_CNT,0)) AS DLY_DLY_CNT09 , SUM(DECODE(SUBSTR(YYYYMM,5,2),'09',LT_TOT_DAY,0)) AS LT_TOT_DAY09 , SUM(DECODE(SUBSTR(YYYYMM,5,2),'09',LT_WORKING_DAY,0)) AS LT_WORKING_DAY09 , SUM(DECODE(SUBSTR(YYYYMM,5,2),'09',LT_DAY,0)) AS LT_DAY09 , SUM(DECODE(SUBSTR(YYYYMM,5,2),'10',DLY_TOT_CNT,0)) AS DLY_TOT_CNT10 , SUM(DECODE(SUBSTR(YYYYMM,5,2),'10',DLY_CNT,0)) AS DLY_DLY_CNT10 , SUM(DECODE(SUBSTR(YYYYMM,5,2),'10',LT_TOT_DAY,0)) AS LT_TOT_DAY10 , SUM(DECODE(SUBSTR(YYYYMM,5,2),'10',LT_WORKING_DAY,0)) AS LT_WORKING_DAY10 , SUM(DECODE(SUBSTR(YYYYMM,5,2),'10',LT_DAY,0)) AS LT_DAY10 , SUM(DECODE(SUBSTR(YYYYMM,5,2),'11',DLY_TOT_CNT,0)) AS DLY_TOT_CNT11 , SUM(DECODE(SUBSTR(YYYYMM,5,2),'11',DLY_CNT,0)) AS DLY_DLY_CNT11 , SUM(DECODE(SUBSTR(YYYYMM,5,2),'11',LT_TOT_DAY,0)) AS LT_TOT_DAY11 , SUM(DECODE(SUBSTR(YYYYMM,5,2),'11',LT_WORKING_DAY,0)) AS LT_WORKING_DAY11 , SUM(DECODE(SUBSTR(YYYYMM,5,2),'11',LT_DAY,0)) AS LT_DAY11 , SUM(DECODE(SUBSTR(YYYYMM,5,2),'12',DLY_TOT_CNT,0)) AS DLY_TOT_CNT12 , SUM(DECODE(SUBSTR(YYYYMM,5,2),'12',DLY_CNT,0)) AS DLY_DLY_CNT12 , SUM(DECODE(SUBSTR(YYYYMM,5,2),'12',LT_TOT_DAY,0)) AS LT_TOT_DAY12 , SUM(DECODE(SUBSTR(YYYYMM,5,2),'12',LT_WORKING_DAY,0)) AS LT_WORKING_DAY12 , SUM(DECODE(SUBSTR(YYYYMM,5,2),'12',LT_DAY,0)) AS LT_DAY12 FROM KPI_DELIVERY KPI,(SELECT BUYER,MIN(KEP_DEPT) AS KEP_DEPT FROM MIS_BUYER_MNG WHERE YEAR = #{st_year} AND STATUS = 'C' GROUP BY BUYER) MIS WHERE 1=1 AND KPI.BUYER != 'KRKEPB0004'
AND YYYYMM LIKE #{st_year}||'%'
AND KPI.DIVISION =#{st_division}
AND (DLY_TOT_CNT != 0 OR LT_TOT_DAY != 0) AND KPI.BUYER= MIS.BUYER GROUP BY MIS.KEP_DEPT , DECODE('N','N','X',KPI.BUYER) ) ORDER BY 1,2
